package com.gymmind.workout.application;
import com.gymmind.coach.application.CoachAssignmentService; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.member.domain.repository.MemberRepository; import com.gymmind.shared.error.*; import com.gymmind.shared.security.*; import com.gymmind.workout.domain.model.WorkoutRecord; import com.gymmind.workout.domain.repository.WorkoutRecordRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; import java.util.stream.Collectors;
@Service public class DefaultTrainingOverviewService implements TrainingOverviewService {
 private final WorkoutRecordRepository records; private final MemberRepository members; private final CoachAssignmentService assignments;
 public DefaultTrainingOverviewService(WorkoutRecordRepository r,MemberRepository m,CoachAssignmentService a){records=r;members=m;assignments=a;}
 @Override @Transactional(readOnly=true) public TrainingOverviewView overview(CurrentActor actor,LocalDate since,LocalDate until,Long memberId){
  if(actor==null||!actor.hasPermission("workout:read")) throw new BusinessException(ErrorCode.FORBIDDEN); Long tenant=ActorAccess.tenantId(actor); boolean platform=actor.isPlatformAdmin()&&tenant==null;
  if(!platform&&tenant==null) throw new BusinessException(ErrorCode.TENANT_CONTEXT_REQUIRED); LocalDate end=until==null?LocalDate.now():until; LocalDate start=since==null?end.minusDays(29):since; if(start.isAfter(end)) throw new BusinessException(ErrorCode.VALIDATION_FAILED);
  List<WorkoutRecord> all=platform?List.of():records.findByTenantIdAndDateBetween(tenant,start,end); if(actor.roles().contains(RoleCode.MEMBER)){Long own=members.findByTenantIdAndUserId(tenant,actor.userId()).map(x->x.getId()).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND)); memberId=own;}
  if(memberId!=null){if(actor.roles().contains(RoleCode.COACH)&&!assignments.canAccess(actor,memberId)) throw new BusinessException(ErrorCode.FORBIDDEN); if(!actor.roles().contains(RoleCode.MEMBER)&&!ActorAccess.canManageTenant(actor)) throw new BusinessException(ErrorCode.FORBIDDEN); Long selectedMemberId=memberId; all=all.stream().filter(x->selectedMemberId.equals(x.getMemberId())).toList();}
  Map<Long,List<WorkoutRecord>> grouped=all.stream().collect(Collectors.groupingBy(WorkoutRecord::getMemberId)); long minutes=all.stream().mapToLong(WorkoutRecord::getDuration).sum(); int streak=calculateStreak(all); List<TrainingOverviewView.MemberSummary> summaries=grouped.entrySet().stream().map(e->{List<WorkoutRecord> rs=e.getValue();var m=members.findByTenantIdAndId(tenant,e.getKey()).orElse(null);return new TrainingOverviewView.MemberSummary(e.getKey(),m==null?"会员 #"+e.getKey():m.getFullName(),rs.size(),rs.stream().mapToInt(WorkoutRecord::getDuration).sum(),rs.stream().map(WorkoutRecord::getWorkoutDate).max(LocalDate::compareTo).orElse(null));}).toList();
  return new TrainingOverviewView(platform?"PLATFORM_ADMIN":actor.roles().stream().findFirst().map(Enum::name).orElse("MEMBER"),start,end,new TrainingOverviewView.Summary(all.size(),grouped.size(),minutes,all.isEmpty()?0:(double)minutes/all.size(),streak),all.stream().map(x->new TrainingOverviewView.RecordView(x.getId(),x.getMemberId(),x.getWorkoutDate(),x.getDuration(),x.getCalories(),x.getNotes(),x.getPlanId())).toList(),summaries);
 }
 private int calculateStreak(List<WorkoutRecord> rs){Set<LocalDate> dates=rs.stream().map(WorkoutRecord::getWorkoutDate).collect(Collectors.toSet());int n=0;LocalDate d=LocalDate.now();while(dates.contains(d)){n++;d=d.minusDays(1);}return n;}
}
